import{_ as t,o as d,c as r,a2 as e}from"./chunks/framework.CAKCj7G0.js";const p=JSON.parse('{"title":"README","description":"","frontmatter":{},"headers":[],"relativePath":"Java/Java/Java语言概览.md","filePath":"Java/Java/Java语言概览.md","lastUpdated":1762838572000}'),i={name:"Java/Java/Java语言概览.md"};function o(n,a,l,h,J,v){return d(),r("div",null,[...a[0]||(a[0]=[e('<h1 id="readme" tabindex="-1">README <a class="header-anchor" href="#readme" aria-label="Permalink to &quot;README&quot;">​</a></h1><h2 id="一、java语言简介" tabindex="-1">一、Java语言简介 <a class="header-anchor" href="#一、java语言简介" aria-label="Permalink to &quot;一、Java语言简介&quot;">​</a></h2><p>Java是由Sun Microsystems（后被Oracle收购）于1995年推出的一门面向对象的编程语言，由詹姆斯·高斯林（James Gosling）及其团队研发。其设计初衷是解决消费电子设备的跨平台编程问题，后凭借“一次编写，到处运行”的核心优势，成为企业级应用开发的主流语言之一。</p><p>核心定位：一门<strong>跨平台、面向对象、</strong> <strong>编译型与解释型结合</strong>的高级编程语言，兼具安全性、可移植性和高性能等特点。</p><h2 id="二、java核心特性" tabindex="-1">二、Java核心特性 <a class="header-anchor" href="#二、java核心特性" aria-label="Permalink to &quot;二、Java核心特性&quot;">​</a></h2><h3 id="_1-跨平台性" tabindex="-1">1. 跨平台性 <a class="header-anchor" href="#_1-跨平台性" aria-label="Permalink to &quot;1. 跨平台性&quot;">​</a></h3><p>这是Java最显著的特性。其实现原理是：Java源代码（.java文件）通过javac编译器编译为字节码文件（.class文件），字节码不直接对应特定操作系统的机器码，而是通过Java虚拟机（JVM）解释执行。不同操作系统只需安装对应版本的JVM，即可运行相同的字节码文件，实现“一次编译，多平台运行”。</p><p>重点：跨平台的核心是JVM，而非Java语言本身；字节码是连接源代码与机器码的中间载体。</p><h3 id="_2-面向对象-oop" tabindex="-1">2. 面向对象（OOP） <a class="header-anchor" href="#_2-面向对象-oop" aria-label="Permalink to &quot;2. 面向对象（OOP）&quot;">​</a></h3><p>Java是纯面向对象的语言（除基本数据类型外），完全遵循面向对象的四大核心思想：</p><ul><li><p><strong>封装</strong>：将数据（属性）和操作数据的方法封装在类中，通过访问修饰符（public、private、protected、default）控制访问权限，隐藏内部实现细节。</p></li><li><p><strong>继承</strong>：允许子类继承父类的非私有属性和方法，实现代码复用；Java支持单继承（一个子类只能有一个直接父类），但可通过接口实现多继承的效果。</p></li><li><p><strong>多态</strong>：同一行为在不同对象上有不同表现形式，分为编译时多态（方法重载）和运行时多态（方法重写，需结合继承和向上转型）。</p></li><li><p><strong>抽象</strong>：通过抽象类或接口抽取共性特征，定义规范而不实现具体逻辑，强制子类实现核心方法。</p></li></ul><h3 id="_3-安全性" tabindex="-1">3. 安全性 <a class="header-anchor" href="#_3-安全性" aria-label="Permalink to &quot;3. 安全性&quot;">​</a></h3><p>Java从设计之初就重视安全性，主要体现在以下方面：</p><ul><li><p>字节码验证：JVM在加载字节码时会验证其合法性，防止恶意代码执行。</p></li><li><p>沙箱机制：限制程序的访问权限，防止程序破坏本地系统资源。</p></li><li><p>垃圾回收（GC）：自动管理内存，减少内存泄漏风险；不支持指针直接操作内存，避免非法内存访问。</p></li></ul><h3 id="_4-编译与解释结合" tabindex="-1">4. 编译与解释结合 <a class="header-anchor" href="#_4-编译与解释结合" aria-label="Permalink to &quot;4. 编译与解释结合&quot;">​</a></h3><p>Java并非纯编译型或纯解释型语言：</p><ul><li><p>编译阶段（编译型）：源代码→字节码（由javac编译器完成，不依赖具体平台）。</p></li><li><p>运行阶段（解释型）：字节码→机器码（由JVM的解释器或即时编译器（JIT）完成，JIT可将热点代码编译为机器码缓存，提升运行效率）。</p></li></ul><h3 id="_5-健壮性" tabindex="-1">5. 健壮性 <a class="header-anchor" href="#_5-健壮性" aria-label="Permalink to &quot;5. 健壮性&quot;">​</a></h3><p>基于GC自动内存管理、异常处理机制（try-catch-finally）等特性，Java能有效减少程序运行时的错误，提升程序的稳定性。</p><h2 id="三、java发展历程与版本演进-关键节点" tabindex="-1">三、Java发展历程与版本演进（关键节点） <a class="header-anchor" href="#三、java发展历程与版本演进-关键节点" aria-label="Permalink to &quot;三、Java发展历程与版本演进（关键节点）&quot;">​</a></h2><p>Java的版本演进伴随功能的不断丰富，以下为重要版本节点：</p><table tabindex="0"><thead><tr><th>发布年份</th><th>版本</th><th>核心里程碑/特性</th></tr></thead><tbody><tr><td>1995</td><td>Java 1.0</td><td>首次正式发布，奠定Java核心语法和JVM基础。</td></tr><tr><td>2004</td><td>Java 5（1.5）</td><td>重大更新，引入泛型、注解、枚举、foreach循环等核心特性。</td></tr><tr><td>2014</td><td>Java 8（1.8）</td><td>至今最主流版本，引入Lambda表达式、Stream API、函数式接口、默认方法等。</td></tr><tr><td>2018</td><td>Java 11</td><td>长期支持（LTS）版本，引入局部变量类型推断（var关键字），移除Oracle JDK商业授权。</td></tr><tr><td>2021</td><td>Java 17</td><td>最新LTS版本，强化安全性，引入密封类、switch表达式优化等特性。</td></tr><tr><td>提示：企业开发中Java 8和Java 17是目前最常用的版本，Java 8兼容性强，Java 17支持更多新特性且为LTS版本。</td><td></td><td></td></tr></tbody></table><h2 id="四、java技术体系-三大核心" tabindex="-1">四、Java技术体系（三大核心） <a class="header-anchor" href="#四、java技术体系-三大核心" aria-label="Permalink to &quot;四、Java技术体系（三大核心）&quot;">​</a></h2><p>Java技术体系围绕不同应用场景分为三大核心模块，覆盖从桌面到企业级应用的全场景：</p><h3 id="_1-java-se-standard-edition-标准版" tabindex="-1">1. Java SE（Standard Edition，标准版） <a class="header-anchor" href="#_1-java-se-standard-edition-标准版" aria-label="Permalink to &quot;1. Java SE（Standard Edition，标准版）&quot;">​</a></h3><p>Java的基础核心，提供Java语言的核心语法、API和运行环境，包括：</p><ul><li><p>核心类库：集合框架（Collection）、IO流、并发编程（Thread、Executor）、异常处理等。</p></li><li><p>运行环境：JVM、JRE（Java Runtime Environment，Java运行时环境）。</p></li></ul><p>定位：Java EE和Java ME的基础，开发桌面应用、控制台程序等。</p><h3 id="_2-java-ee-enterprise-edition-企业版" tabindex="-1">2. Java EE（Enterprise Edition，企业版） <a class="header-anchor" href="#_2-java-ee-enterprise-edition-企业版" aria-label="Permalink to &quot;2. Java EE（Enterprise Edition，企业版）&quot;">​</a></h3><p>基于Java SE扩展，面向企业级分布式应用开发，提供服务器端开发的规范和API，包括：</p><ul><li><p>核心规范：Servlet、JSP（Java Server Pages）、Spring、Hibernate、MyBatis等（其中Spring生态是目前企业级开发的主流）。</p></li><li><p>应用场景：网站后台、分布式系统、微服务架构等。</p></li></ul><p>注意：Java EE已被Oracle捐赠给Eclipse基金会，更名为Jakarta EE，但核心规范和应用场景未变。</p><h3 id="_3-java-me-micro-edition-微型版" tabindex="-1">3. Java ME（Micro Edition，微型版） <a class="header-anchor" href="#_3-java-me-micro-edition-微型版" aria-label="Permalink to &quot;3. Java ME（Micro Edition，微型版）&quot;">​</a></h3><p>基于Java SE精简，面向嵌入式设备和移动设备开发，如早期的功能手机应用、智能家电等。随着智能手机操作系统（iOS、Android）的兴起，其应用场景逐渐萎缩，目前使用较少。</p><h2 id="五、java运行环境-jdk、jre、jvm关系" tabindex="-1">五、Java运行环境（JDK、JRE、JVM关系） <a class="header-anchor" href="#五、java运行环境-jdk、jre、jvm关系" aria-label="Permalink to &quot;五、Java运行环境（JDK、JRE、JVM关系）&quot;">​</a></h2><p>这三者是Java运行的核心基础，需明确其区别与联系：</p><ul><li><p><strong>JVM（Java Virtual Machine，Java虚拟机）</strong>：核心组件，负责将字节码解释为机器码并执行，是跨平台的关键；不同操作系统有不同的JVM实现。</p></li><li><p><strong>JRE（Java Runtime Environment，Java运行时环境）</strong>：运行Java程序的最小环境，包含JVM和Java核心类库（如java.lang包）；用户运行Java程序只需安装JRE。</p></li><li><p><strong>JDK（Java Development Kit，Java开发工具包）</strong>：开发Java程序的工具包，包含JRE、编译器（javac）、调试工具（jdb）等开发工具；开发者必须安装JDK。</p></li></ul><p>核心关系：JDK ⊇ JRE ⊇ JVM</p><h2 id="六、与其他主流编程语言的比较" tabindex="-1">六、与其他主流编程语言的比较 <a class="header-anchor" href="#六、与其他主流编程语言的比较" aria-label="Permalink to &quot;六、与其他主流编程语言的比较&quot;">​</a></h2><p>Java在编程语言生态中占据重要地位，通过与Python、C++、Go等主流语言的对比，可更清晰定位其优势与适用场景：</p><table tabindex="0"><thead><tr><th>对比维度</th><th>Java</th><th>Python</th><th>C++</th><th>Go</th></tr></thead><tbody><tr><td><strong>语言类型</strong></td><td>面向对象、编译+解释结合</td><td>多范式（面向对象+函数式）、纯解释型</td><td>面向对象/过程、纯编译型</td><td>多范式（面向过程+对象）、纯编译型</td></tr><tr><td><strong>跨平台性</strong></td><td>强（依赖JVM，一次编译多平台运行）</td><td>强（依赖Python解释器，跨平台无需修改代码）</td><td>弱（编译后生成平台相关机器码，需跨平台重编译）</td><td>较强（编译为平台相关机器码，但支持交叉编译）</td></tr><tr><td><strong>性能</strong></td><td>中高（JIT即时编译优化后接近编译型语言）</td><td>低（解释执行，GIL锁限制并发性能）</td><td>极高（直接操作内存，无虚拟机开销）</td><td>高（编译型无虚拟机，轻量级协程优化并发）</td></tr><tr><td><strong>开发效率</strong></td><td>中（语法严谨，需手动管理部分细节，生态成熟）</td><td>高（语法简洁，动态类型，库丰富）</td><td>低（需手动管理内存，语法复杂）</td><td>高（语法简洁，内置并发支持，编译快速）</td></tr><tr><td><strong>内存管理</strong></td><td>自动（GC垃圾回收，无需手动释放）</td><td>自动（引用计数+GC，管理更智能）</td><td>手动（需通过new/delete管理，易内存泄漏）</td><td>自动（简单GC，内存占用低）</td></tr><tr><td><strong>核心优势</strong></td><td>生态成熟、企业级应用稳定、跨平台兼容</td><td>数据分析、AI/ML、脚本开发效率高</td><td>底层开发、高性能场景（游戏/引擎）</td><td>高并发、微服务、云原生开发轻量高效</td></tr><tr><td><strong>典型应用场景</strong></td><td>企业后端、Android开发、大数据（Hadoop生态）</td><td>数据分析、AI、自动化脚本、Web后端（Django/Flask）</td><td>游戏引擎、操作系统内核、嵌入式开发</td><td>微服务、云原生应用、分布式系统、中间件</td></tr><tr><td>总结：无绝对最优语言，需结合场景选择——企业级稳定后端优先Java，AI/数据分析选Python，高性能底层选C++，云原生微服务选Go。</td><td></td><td></td><td></td><td></td></tr></tbody></table>',41)])])}const c=t(i,[["render",o]]);export{p as __pageData,c as default};
